import urllib.request
import time
import socket

class RateLimitError(Exception):
    pass

class ServerError(Exception):
    pass

class ClientError(Exception):
    pass

class ConnectionError(Exception):
    pass

class APIClient:
    def __init__(self, base_url, timeout=10):
        self.base_url = base_url
        self.timeout = timeout

    def get(self, path):
        url = self.base_url + path
        retry_429 = 0
        max_429_retries = 3
        backoff_times = [0.5, 1, 2]

        retry_5xx = False
        max_5xx_retries = 1
        backoff_5xx = 1

        retry_network = False
        max_network_retries = 1
        backoff_network = 1

        while True:
            try:
                req = urllib.request.Request(url)
                with urllib.request.urlopen(req, timeout=self.timeout) as response:
                    status = response.status
                    body = response.read().decode('utf-8')
                    return body

            except urllib.error.HTTPError as e:
                status = e.code
                if status == 429:
                    if retry_429 < max_429_retries:
                        retry_429 += 1
                        time.sleep(backoff_times[retry_429 - 1])
                        continue
                    else:
                        raise RateLimitError(f"Rate limit exceeded after {max_429_retries} retries")
                elif 500 <= status < 600:
                    if not retry_5xx:
                        retry_5xx = True
                        time.sleep(backoff_5xx)
                        continue
                    else:
                        raise ServerError(f"Server error {status}")
                elif 400 <= status < 500:
                    raise ClientError(f"Client error {status}")
                else:
                    # Other HTTP errors (e.g., 404) treated as 4xx per requirement
                    raise ClientError(f"HTTP error {status}")

            except urllib.error.URLError as e:
                if not retry_network:
                    retry_network = True
                    time.sleep(backoff_network)
                    continue
                else:
                    raise ConnectionError(f"Network error: {e.reason}")
